// Icon svgs

import { useId } from "react";

type EyeProps = Omit<React.SVGProps<SVGSVGElement>, "ref"> & {
  slashed?: boolean;
};

export function Eye({ slashed = false, className, ...props }: EyeProps) {
  const maskId = useId();

  // length of the diagonal line (≈ sqrt(18² + 18²))
  const LENGTH = 26;

  const slashStyle: React.CSSProperties = {
    strokeDasharray: LENGTH,
    strokeDashoffset: slashed ? 0 : LENGTH,
  };

  const slashClassName =
    "transition-[stroke-dashoffset] duration-200 ease-in-out motion-reduce:transition-none";

  return (
    <svg
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      {...props}
    >
      {/* Cuts a small gap in the eye where the slash passes */}
      <mask id={maskId}>
        <rect width="24" height="24" fill="white" />
        <path
          d="M3 21L21 3"
          stroke="black"
          strokeWidth="4"
          strokeLinecap="round"
          style={slashStyle}
          className={slashClassName}
        />
      </mask>

      <g
        mask={`url(#${maskId})`}
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d="M15.5799 11.9999C15.5799 13.9799 13.9799 15.5799 11.9999 15.5799C10.0199 15.5799 8.41992 13.9799 8.41992 11.9999C8.41992 10.0199 10.0199 8.41992 11.9999 8.41992C13.9799 8.41992 15.5799 10.0199 15.5799 11.9999Z" />
        <path d="M11.9998 20.2702C15.5298 20.2702 18.8198 18.1902 21.1098 14.5902C22.0098 13.1802 22.0098 10.8102 21.1098 9.40021C18.8198 5.80021 15.5298 3.72021 11.9998 3.72021C8.46984 3.72021 5.17984 5.80021 2.88984 9.40021C1.98984 10.8102 1.98984 13.1802 2.88984 14.5902C5.17984 18.1902 8.46984 20.2702 11.9998 20.2702Z" />
      </g>

      {/* The slash itself */}
      <path
        d="M3 21L21 3"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        style={slashStyle}
        className={slashClassName}
      />
    </svg>
  );
}

